import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, session, redirect
from functools import wraps
import subprocess
import shlex

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/tmp/reports.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS reports (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        author TEXT NOT NULL,
        format TEXT DEFAULT 'pdf',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'viewer'
    )''')
    db.commit()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/reports', methods=['GET'])
@require_auth
def list_reports():
    db = get_db()
    author_filter = request.args.get('author', '')
    sort_col = request.args.get('sort', 'created_at')
    # Whitelist sort columns
    allowed_sorts = ['created_at', 'title', 'author', 'id']
    if sort_col not in allowed_sorts:
        sort_col = 'created_at'
    if author_filter:
        query = f"SELECT * FROM reports WHERE author = '{author_filter}' ORDER BY {sort_col}"
    else:
        query = f"SELECT * FROM reports ORDER BY {sort_col}"
    rows = db.execute(query).fetchall()
    return jsonify([dict(r) for r in rows])

@app.route('/api/reports', methods=['POST'])
@require_auth
def create_report():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    db = get_db()
    db.execute(
        'INSERT INTO reports (title, author, format) VALUES (?, ?, ?)',
        (data['title'], session.get('username', 'anonymous'), data.get('format', 'pdf'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/reports/<int:report_id>/export', methods=['POST'])
@require_auth
def export_report(report_id):
    db = get_db()
    report = db.execute('SELECT * FROM reports WHERE id = ?', (report_id,)).fetchone()
    if not report:
        return jsonify({'error': 'not found'}), 404

    output_dir = os.environ.get('EXPORT_DIR', '/tmp/exports')
    os.makedirs(output_dir, exist_ok=True)

    fmt = report['format'] if report['format'] in ('pdf', 'csv', 'html') else 'pdf'
    filename = f"report_{report_id}.{fmt}"
    filepath = os.path.join(output_dir, filename)

    # Generate export using system tool
    title_safe = report['title']
    cmd = f"echo '{title_safe}' > {filepath}"
    subprocess.run(cmd, shell=True, timeout=5)

    return jsonify({'status': 'exported', 'path': filepath})

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400
    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?', (data.get('username', ''),)
    ).fetchone()
    if user and user['password_hash'] == hashlib.sha256(data.get('password', '').encode()).hexdigest():
        session['user_id'] = user['id']
        session['username'] = user['username']
        session['role'] = user['role']
        return jsonify({'status': 'ok'})
    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
